// async/await: stackless, Promise-based. Typing forces the result contract.
async function handle(id: string): Promise<Result> {   // must be awaited by the caller
    const user   = await fetchUser(id);
    const orders = await fetchOrders(user.id);
    return { user, orders };
}

// async generators: an AsyncIterable stream with backpressure per element.
async function* rows(cursor: AsyncCursor): AsyncGenerator<Row, void, undefined> {
    while (true) {
        const batch = await cursor.next();
        if (batch.done) return;
        for (const r of batch.rows) yield r;   // yield suspends; the consumer pulls
    }
}
for await (const row of rows(cursor)) { process(row); }   // typed, checked iteration

// NEVER block the carrier: a synchronous heavy loop inside an async function
// stalls every other task on the event loop. Chunk it with awaits or a Worker.
